public class Harness {
    public static void main(String[] args) {
        class Counting extends java.util.AbstractList<Integer> { int reads=0; int[] data={-1,2,3}; public int size(){return data.length;} public Integer get(int i){reads++; return data[i];} }
        Counting xs = new Counting();
        java.util.stream.Stream<Integer> s = Main.positiveStream(xs);
        System.out.println(xs.reads);
        System.out.println(s.toList());
        System.out.println(xs.reads > 0);
        System.out.println(Main.positiveStream(java.util.List.of()).count());
    }
}

